/* ============================================================  --  RACE DAY - DATABASE CREATION SCRIPT  --  PROG6212 - Portfolio of Evidence - Part 1  --  Author: [Your Name]  --  Date: 2026-09-03  --  ============================================================  --  This script creates the full database schema for the RaceDay  --  event management system. It includes all 7 entities, their  --  relationships, constraints, and seed data.  --  Run this script in SQL Server Management Studio (SSMS) on a  --  clean database.  ============================================================ */  -- 1. Create the database (run this first, then switch to the new DB) CREATE DATABASE RaceDay; GO  USE RaceDay; GO  -- 2. Drop tables if they exist (for clean re-runs) IF OBJECT_ID('dbo.Notifications', 'U') IS NOT NULL DROP TABLE Notifications; IF OBJECT_ID('dbo.Results', 'U') IS NOT NULL DROP TABLE Results; IF OBJECT_ID('dbo.Enrolments', 'U') IS NOT NULL DROP TABLE Enrolments; IF OBJECT_ID('dbo.Categories', 'U') IS NOT NULL DROP TABLE Categories; IF OBJECT_ID('dbo.Events', 'U') IS NOT NULL DROP TABLE Events; IF OBJECT_ID('dbo.Profiles', 'U') IS NOT NULL DROP TABLE Profiles; IF OBJECT_ID('dbo.Users', 'U') IS NOT NULL DROP TABLE Users; GO  /* ============================================================  TABLE: Users  --  Stores all system users. The 'role' column distinguishes  --  between Organisers and Participants.  --  One table for both roles avoids duplicating login columns.  ============================================================ */ CREATE TABLE Users (     user_id         INT             IDENTITY(1,1) PRIMARY KEY,     email           VARCHAR(255)    NOT NULL UNIQUE,     password_hash   VARCHAR(255)    NOT NULL,     first_name      VARCHAR(100)    NOT NULL,     last_name       VARCHAR(100)    NOT NULL,     role            VARCHAR(20)     NOT NULL         CONSTRAINT CHK_User_Role CHECK (role IN ('Organiser', 'Participant')),     created_at      DATETIME        NOT NULL DEFAULT GETDATE() ); GO  /* ============================================================  TABLE: Profiles  --  Extended personal information for every user.  --  1:1 relationship with Users (one user has one profile).  ============================================================ */ CREATE TABLE Profiles (     profile_id                  INT             IDENTITY(1,1) PRIMARY KEY,     user_id                     INT             NOT NULL UNIQUE,          -- FK to Users     date_of_birth               DATE            NULL,     emergency_contact_name      VARCHAR(100)    NULL,     emergency_contact_phone     VARCHAR(20)     NULL,     medical_conditions          VARCHAR(500)    NULL,     profile_picture_url         VARCHAR(500)    NULL,      CONSTRAINT FK_Profiles_Users         FOREIGN KEY (user_id) REFERENCES Users(user_id)         ON DELETE CASCADE ); GO  /* ============================================================  TABLE: Events  --  Races created by Organisers.  --  FK organiser_id links back to Users.  ============================================================ */ CREATE TABLE Events (     event_id        INT             IDENTITY(1,1) PRIMARY KEY,     organiser_id    INT             NOT NULL,          -- FK to Users (Organiser)     name            VARCHAR(200)    NOT NULL,     description     VARCHAR(1000)   NULL,     event_date      DATE            NOT NULL,     location        VARCHAR(200)    NOT NULL,     distance        DECIMAL(6,2)    NOT NULL,     event_type      VARCHAR(20)     NOT NULL         CONSTRAINT CHK_Event_Type CHECK (event_type IN ('run', 'walk', 'cycle')),     created_at      DATETIME        NOT NULL DEFAULT GETDATE(),      CONSTRAINT FK_Events_Users         FOREIGN KEY (organiser_id) REFERENCES Users(user_id)         ON DELETE CASCADE ); GO  /* ============================================================  TABLE: Categories  --  Age or distance categories within an event.  --  Each event can have multiple categories (1:N).  ============================================================ */ CREATE TABLE Categories (     category_id     INT             IDENTITY(1,1) PRIMARY KEY,     event_id        INT             NOT NULL,          -- FK to Events     category_name   VARCHAR(100)    NOT NULL,     age_range       VARCHAR(50)     NULL,     distance        DECIMAL(6,2)    NULL,      CONSTRAINT FK_Categories_Events         FOREIGN KEY (event_id) REFERENCES Events(event_id)         ON DELETE CASCADE ); GO  /* ============================================================  TABLE: Enrolments  --  Links a Participant to an Event + Category.  --  This is the central junction table for the system.  ============================================================ */ CREATE TABLE Enrolments (     enrolment_id    INT             IDENTITY(1,1) PRIMARY KEY,     user_id         INT             NOT NULL,          -- FK to Users (Participant)     event_id        INT             NOT NULL,          -- FK to Events     category_id     INT             NOT NULL,          -- FK to Categories     enrolment_date  DATETIME        NOT NULL DEFAULT GETDATE(),     status          VARCHAR(20)     NOT NULL DEFAULT 'Pending'         CONSTRAINT CHK_Enrolment_Status CHECK (status IN ('Pending', 'Confirmed', 'Cancelled', 'Completed', 'Archived')),      CONSTRAINT FK_Enrolments_Users         FOREIGN KEY (user_id) REFERENCES Users(user_id)         ON DELETE CASCADE,     CONSTRAINT FK_Enrolments_Events         FOREIGN KEY (event_id) REFERENCES Events(event_id)         ON DELETE CASCADE,     CONSTRAINT FK_Enrolments_Categories         FOREIGN KEY (category_id) REFERENCES Categories(category_id)         ON DELETE NO ACTION ); GO  /* ============================================================  TABLE: Results  --  Finish times and positions recorded after a race.  --  1:1 relationship with Enrolments (one result per enrolment).  ============================================================ */ CREATE TABLE Results (     result_id           INT             IDENTITY(1,1) PRIMARY KEY,     enrolment_id        INT             NOT NULL UNIQUE,     -- FK to Enrolments     finish_time         TIME            NULL,     finishing_position  INT             NULL,      CONSTRAINT FK_Results_Enrolments         FOREIGN KEY (enrolment_id) REFERENCES Enrolments(enrolment_id)         ON DELETE CASCADE ); GO  /* ============================================================  TABLE: Notifications  --  System messages sent to users about events.  --  Simplified design — one table, not a full messaging platform.  ============================================================ */ CREATE TABLE Notifications (     notification_id     INT             IDENTITY(1,1) PRIMARY KEY,     user_id             INT             NOT NULL,          -- FK to Users (recipient)     event_id            INT             NULL,              -- FK to Events (optional context)     message             VARCHAR(500)    NOT NULL,     created_at          DATETIME        NOT NULL DEFAULT GETDATE(),     is_read             BIT             NOT NULL DEFAULT 0,      CONSTRAINT FK_Notifications_Users         FOREIGN KEY (user_id) REFERENCES Users(user_id)         ON DELETE CASCADE,     CONSTRAINT FK_Notifications_Events         FOREIGN KEY (event_id) REFERENCES Events(event_id)         ON DELETE NO ACTION ); GO  /* ============================================================  SEED DATA  --  Minimum requirements:  --   2 Organisers, 2 Participants  --   3 Events with Categories  --   Sample Enrolments  ============================================================ */  -- ORGANISERS INSERT INTO Users (email, password_hash, first_name, last_name, role) VALUES  ('thabo.m@raceday.co.za',  'hashed_pw_1', 'Thabo', 'Mokoena', 'Organiser'), ('lerato.k@raceday.co.za', 'hashed_pw_2', 'Lerato', 'Khumalo', 'Organiser');  -- PARTICIPANTS INSERT INTO Users (email, password_hash, first_name, last_name, role) VALUES  ('sipho.d@gmail.com', 'hashed_pw_3', 'Sipho', 'Dlamini', 'Participant'), ('amanda.n@gmail.com', 'hashed_pw_4', 'Amanda', 'Naidoo', 'Participant');  -- PROFILES (one per user) INSERT INTO Profiles (user_id, date_of_birth, emergency_contact_name, emergency_contact_phone, medical_conditions) VALUES  (1, '1985-03-15', 'Mrs Mokoena', '0821112222', 'None'), (2, '1990-07-22', 'Mr Khumalo', '0833334444', 'Asthma'), (3, '1995-11-08', 'Mr Dlamini', '0845556666', 'None'), (4, '1988-01-30', 'Mrs Naidoo', '0857778888', 'Penicillin allergy');  -- EVENTS (parody names of South African races) INSERT INTO Events (organiser_id, name, description, event_date, location, distance, event_type) VALUES  (1, 'Comrades Clash Marathon', 'The ultimate test of endurance between two great cities.', '2026-10-18', 'Pietermaritzburg to Durban', 89.00, 'run'), (1, 'Cape Coast Circuit Tour', 'A scenic cycle around the peninsula with ocean views.', '2026-11-08', 'Cape Town', 109.00, 'cycle'), (2, 'Soweto Showdown Marathon', 'A race through the historic streets of Soweto.', '2026-09-20', 'Soweto, Johannesburg', 42.20, 'run'), (2, 'Twin Valleys Marathon', 'A challenging route through two lush valleys.', '2026-12-06', 'Cape Town', 56.00, 'run');  -- CATEGORIES (age/distance categories for each event) -- Event 1: Comrades Clash Marathon INSERT INTO Categories (event_id, category_name, age_range, distance) VALUES  (1, 'Senior Men', '20-34', 89.00), (1, 'Senior Women', '20-34', 89.00), (1, 'Veteran Men', '35-49', 89.00);  -- Event 2: Cape Coast Circuit Tour INSERT INTO Categories (event_id, category_name, age_range, distance) VALUES  (2, 'Elite Cyclists', 'Open', 109.00), (2, 'Amateur Cyclists', 'Open', 109.00);  -- Event 3: Soweto Showdown Marathon INSERT INTO Categories (event_id, category_name, age_range, distance) VALUES  (3, 'Full Marathon', 'Open', 42.20), (3, 'Half Marathon', 'Open', 21.10);  -- Event 4: Twin Valleys Marathon INSERT INTO Categories (event_id, category_name, age_range, distance) VALUES  (4, 'Ultra Distance', 'Open', 56.00), (4, 'Short Course', 'Open', 21.00);  -- ENROLMENTS (sample sign-ups) INSERT INTO Enrolments (user_id, event_id, category_id, enrolment_date, status) VALUES  (3, 1, 1, '2026-08-01 10:30:00', 'Confirmed'),   -- Sipho in Comrades Clash, Senior Men (3, 2, 5, '2026-08-05 14:15:00', 'Pending'),     -- Sipho in Cape Coast, Amateur Cyclists (4, 3, 7, '2026-08-10 09:00:00', 'Confirmed'),   -- Amanda in Soweto Showdown, Full Marathon (4, 4, 9, '2026-08-12 16:45:00', 'Pending');     -- Amanda in Twin Valleys, Short Course  -- RESULTS (finish data for completed events) INSERT INTO Results (enrolment_id, finish_time, finishing_position) VALUES  (1, '05:42:18', 247),   -- Sipho finished Comrades Clash (3, '03:15:22', 89);      -- Amanda finished Soweto Showdown  -- NOTIFICATIONS (system messages) INSERT INTO Notifications (user_id, event_id, message, is_read) VALUES  (3, 1, 'Your enrolment for Comrades Clash Marathon has been confirmed.', 1), (3, 2, 'Reminder: Cape Coast Circuit Tour starts at 06:00 AM.', 0), (4, 3, 'Soweto Showdown Marathon route map has been updated.', 1), (4, NULL, 'Welcome to RaceDay! Complete your profile to get started.', 0);  GO  /* ============================================================  VERIFICATION QUERIES  --  Uncomment these to verify your data after running the script.  ============================================================ */  -- SELECT * FROM Users; -- SELECT * FROM Profiles; -- SELECT * FROM Events; -- SELECT * FROM Categories; -- SELECT * FROM Enrolments; -- SELECT * FROM Results; -- SELECT * FROM Notifications;  -- Show all enrolments with user and event details -- SELECT  --     e.enrolment_id, --     u.first_name + ' ' + u.last_name AS participant_name, --     ev.name AS event_name, --     c.category_name, --     e.status -- FROM Enrolments e -- JOIN Users u ON e.user_id = u.user_id -- JOIN Events ev ON e.event_id = ev.event_id -- JOIN Categories c ON e.category_id = c.category_id;  -- Show results with participant and event details -- SELECT  --     r.result_id, --     u.first_name + ' ' + u.last_name AS participant_name, --     ev.name AS event_name, --     r.finish_time, --     r.finishing_position -- FROM Results r -- JOIN Enrolments e ON r.enrolment_id = e.enrolment_id -- JOIN Users u ON e.user_id = u.user_id -- JOIN Events ev ON e.event_id = ev.event_id;  GO 